-- check: account_summary.grain_uniqueness (account_number, transaction_date)
SELECT count(*) AS duplicate_groups, COALESCE(sum(n), 0) AS rows_in_duplicate_groups
FROM (SELECT "account_number", "transaction_date", count(*) AS n FROM analytics_poc.v_account_summary GROUP BY "account_number", "transaction_date" HAVING count(*) > 1);

-- ===== dim_adm =====
-- check: dim_adm.row_structure
SELECT 'dim_adm' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim(replace("restructure_flag", chr(13), '')), ''), 'NULL') IS NULL) AS rows_with_empty_last_column
FROM analytics_poc.raw_dim_adm;
-- check: dim_adm.conversion_failures
SELECT 'dim_adm' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim("transaction_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("transaction_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "transaction_date__fail",
  count_if(NULLIF(NULLIF(trim("disbursement_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("disbursement_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "disbursement_date__fail",
  count_if(NULLIF(NULLIF(trim("interest_rate"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("interest_rate"), ''), 'NULL'), ',', '') AS decimal(12,8)) IS NULL) AS "interest_rate__fail",
  count_if(NULLIF(NULLIF(trim("delayed_charge_rate"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("delayed_charge_rate"), ''), 'NULL'), ',', '') AS decimal(12,8)) IS NULL) AS "delayed_charge_rate__fail",
  count_if(NULLIF(NULLIF(trim("tenure"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("tenure"), ''), 'NULL') AS integer) IS NULL) AS "tenure__fail",
  count_if(NULLIF(NULLIF(trim("sanctioned_amount"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("sanctioned_amount"), ''), 'NULL'), ',', '') AS decimal(18,2)) IS NULL) AS "sanctioned_amount__fail",
  count_if(NULLIF(NULLIF(trim("disbursed_amount"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("disbursed_amount"), ''), 'NULL'), ',', '') AS decimal(18,2)) IS NULL) AS "disbursed_amount__fail",
  count_if(NULLIF(NULLIF(trim("ac_closed_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("ac_closed_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "ac_closed_date__fail",
  count_if(NULLIF(NULLIF(trim("npa_flag"), ''), 'NULL') IS NOT NULL AND CASE WHEN upper(NULLIF(NULLIF(trim("npa_flag"), ''), 'NULL')) IN ('Y', 'YES', 'TRUE', 'T', '1') THEN true WHEN upper(NULLIF(NULLIF(trim("npa_flag"), ''), 'NULL')) IN ('N', 'NO', 'FALSE', 'F', '0') THEN false END IS NULL) AS "npa_flag__fail",
  count_if(NULLIF(NULLIF(trim("npa_marking_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("npa_marking_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "npa_marking_date__fail",
  count_if(NULLIF(NULLIF(trim("npa_unmarking_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("npa_unmarking_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "npa_unmarking_date__fail",
  count_if(NULLIF(NULLIF(trim("actual_loan_tenure"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("actual_loan_tenure"), ''), 'NULL') AS integer) IS NULL) AS "actual_loan_tenure__fail",
  count_if(NULLIF(NULLIF(trim("sanction_limit"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("sanction_limit"), ''), 'NULL'), ',', '') AS decimal(18,2)) IS NULL) AS "sanction_limit__fail",
  count_if(NULLIF(NULLIF(trim("sanction_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("sanction_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "sanction_date__fail",
  count_if(NULLIF(NULLIF(trim("lei_expiry_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("lei_expiry_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "lei_expiry_date__fail",
  count_if(NULLIF(NULLIF(trim("tenure_bucket_order"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("tenure_bucket_order"), ''), 'NULL') AS integer) IS NULL) AS "tenure_bucket_order__fail",
  count_if(NULLIF(NULLIF(trim("roi_bucket_order"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("roi_bucket_order"), ''), 'NULL') AS integer) IS NULL) AS "roi_bucket_order__fail",
  count_if(NULLIF(NULLIF(trim("loan_book_order"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("loan_book_order"), ''), 'NULL') AS integer) IS NULL) AS "loan_book_order__fail",
  count_if(NULLIF(NULLIF(trim("ticket_size_order"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("ticket_size_order"), ''), 'NULL') AS integer) IS NULL) AS "ticket_size_order__fail",
  count_if(NULLIF(NULLIF(trim("nca_flag"), ''), 'NULL') IS NOT NULL AND CASE WHEN upper(NULLIF(NULLIF(trim("nca_flag"), ''), 'NULL')) IN ('Y', 'YES', 'TRUE', 'T', '1') THEN true WHEN upper(NULLIF(NULLIF(trim("nca_flag"), ''), 'NULL')) IN ('N', 'NO', 'FALSE', 'F', '0') THEN false END IS NULL) AS "nca_flag__fail",
  count_if(NULLIF(NULLIF(trim("customer_onboard_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("customer_onboard_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "customer_onboard_date__fail",
  count_if(NULLIF(NULLIF(trim("write_off_tag"), ''), 'NULL') IS NOT NULL AND CASE WHEN upper(NULLIF(NULLIF(trim("write_off_tag"), ''), 'NULL')) IN ('Y', 'YES', 'TRUE', 'T', '1') THEN true WHEN upper(NULLIF(NULLIF(trim("write_off_tag"), ''), 'NULL')) IN ('N', 'NO', 'FALSE', 'F', '0') THEN false END IS NULL) AS "write_off_tag__fail",
  count_if(NULLIF(NULLIF(trim("write_off_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("write_off_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "write_off_date__fail",
  count_if(NULLIF(NULLIF(trim("write_off_amount"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("write_off_amount"), ''), 'NULL'), ',', '') AS decimal(18,2)) IS NULL) AS "write_off_amount__fail",
  count_if(NULLIF(NULLIF(trim("msme_order"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("msme_order"), ''), 'NULL') AS integer) IS NULL) AS "msme_order__fail",
  count_if(NULLIF(NULLIF(trim(replace("restructure_flag", chr(13), '')), ''), 'NULL') IS NOT NULL AND CASE WHEN upper(NULLIF(NULLIF(trim(replace("restructure_flag", chr(13), '')), ''), 'NULL')) IN ('Y', 'YES', 'TRUE', 'T', '1') THEN true WHEN upper(NULLIF(NULLIF(trim(replace("restructure_flag", chr(13), '')), ''), 'NULL')) IN ('N', 'NO', 'FALSE', 'F', '0') THEN false END IS NULL) AS "restructure_flag__fail"
