-- check: dim_adm.grain_uniqueness (account_number, transaction_date)
SELECT count(*) AS duplicate_groups, COALESCE(sum(n), 0) AS rows_in_duplicate_groups
FROM (SELECT "account_number", "transaction_date", count(*) AS n FROM analytics_poc.v_dim_adm GROUP BY "account_number", "transaction_date" HAVING count(*) > 1);

