FROM analytics_poc.raw_dim_calendar;
-- check: dim_calendar.conversion_failures
SELECT 'dim_calendar' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim("date_key"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("date_key"), ''), 'NULL') AS integer) IS NULL) AS "date_key__fail",
  count_if(NULLIF(NULLIF(trim("day_of_the_month"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("day_of_the_month"), ''), 'NULL') AS integer) IS NULL) AS "day_of_the_month__fail",
  count_if(NULLIF(NULLIF(trim("day_of_the_week"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("day_of_the_week"), ''), 'NULL') AS integer) IS NULL) AS "day_of_the_week__fail",
  count_if(NULLIF(NULLIF(trim("day_of_week_in_month"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("day_of_week_in_month"), ''), 'NULL') AS integer) IS NULL) AS "day_of_week_in_month__fail",
  count_if(NULLIF(NULLIF(trim("day_of_the_year"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("day_of_the_year"), ''), 'NULL') AS integer) IS NULL) AS "day_of_the_year__fail",
  count_if(NULLIF(NULLIF(trim("is_weekend"), ''), 'NULL') IS NOT NULL AND CASE WHEN upper(NULLIF(NULLIF(trim("is_weekend"), ''), 'NULL')) IN ('Y', 'YES', 'TRUE', 'T', '1') THEN true WHEN upper(NULLIF(NULLIF(trim("is_weekend"), ''), 'NULL')) IN ('N', 'NO', 'FALSE', 'F', '0') THEN false END IS NULL) AS "is_weekend__fail",
  count_if(NULLIF(NULLIF(trim("iso_week"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("iso_week"), ''), 'NULL') AS integer) IS NULL) AS "iso_week__fail",
  count_if(NULLIF(NULLIF(trim("first_day_of_iso_week"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("first_day_of_iso_week"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "first_day_of_iso_week__fail",
  count_if(NULLIF(NULLIF(trim("last_day_of_iso_week"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("last_day_of_iso_week"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "last_day_of_iso_week__fail",
  count_if(NULLIF(NULLIF(trim("week_of_month"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("week_of_month"), ''), 'NULL') AS integer) IS NULL) AS "week_of_month__fail",
  count_if(NULLIF(NULLIF(trim("calendar_month_number"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("calendar_month_number"), ''), 'NULL') AS integer) IS NULL) AS "calendar_month_number__fail",
  count_if(NULLIF(NULLIF(trim("first_day_of_month"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("first_day_of_month"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "first_day_of_month__fail",
  count_if(NULLIF(NULLIF(trim("last_day_of_month"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("last_day_of_month"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "last_day_of_month__fail",
  count_if(NULLIF(NULLIF(trim("calendar_quarter"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("calendar_quarter"), ''), 'NULL') AS integer) IS NULL) AS "calendar_quarter__fail",
  count_if(NULLIF(NULLIF(trim("first_day_of_quarter"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("first_day_of_quarter"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "first_day_of_quarter__fail",
