-- check: dim_customers.row_structure
SELECT 'dim_customers' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim("derived_cic_type"), ''), 'NULL') IS NULL) AS rows_with_empty_last_column
FROM analytics_poc.raw_dim_customers;
-- check: dim_customers.conversion_failures
SELECT 'dim_customers' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim("date_of_birth_or_incorporation"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("date_of_birth_or_incorporation"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "date_of_birth_or_incorporation__fail",
  count_if(NULLIF(NULLIF(trim("annual_income"), ''), 'NULL') IS NOT NULL AND try_cast(replace(NULLIF(NULLIF(trim("annual_income"), ''), 'NULL'), ',', '') AS decimal(18,2)) IS NULL) AS "annual_income__fail",
  count_if(NULLIF(NULLIF(trim("record_ins_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("record_ins_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "record_ins_date__fail",
  count_if(NULLIF(NULLIF(trim("rn"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("rn"), ''), 'NULL') AS integer) IS NULL) AS "rn__fail",
  count_if(NULLIF(NULLIF(trim("report_date"), ''), 'NULL') IS NOT NULL AND CAST(COALESCE(try(date_parse(NULLIF(NULLIF(trim("report_date"), ''), 'NULL'), '%Y-%m-%d'))) AS date) IS NULL) AS "report_date__fail"
FROM analytics_poc.raw_dim_customers;
