-- check: dim_customers.grain_uniqueness (customer_id)
SELECT count(*) AS duplicate_groups, COALESCE(sum(n), 0) AS rows_in_duplicate_groups
FROM (SELECT "customer_id", count(*) AS n FROM analytics_poc.v_dim_customers GROUP BY "customer_id" HAVING count(*) > 1);

-- ===== dim_par_bucket =====
-- check: dim_par_bucket.row_structure
SELECT 'dim_par_bucket' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim(replace("par_bucket_order", chr(13), '')), ''), 'NULL') IS NULL) AS rows_with_empty_last_column
FROM analytics_poc.raw_dim_par_bucket;
-- check: dim_par_bucket.conversion_failures
SELECT 'dim_par_bucket' AS table_name, count(*) AS row_count,
  count_if(NULLIF(NULLIF(trim("od_days"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("od_days"), ''), 'NULL') AS integer) IS NULL) AS "od_days__fail",
  count_if(NULLIF(NULLIF(trim("interval_split_yearly_sort_order"), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim("interval_split_yearly_sort_order"), ''), 'NULL') AS integer) IS NULL) AS "interval_split_yearly_sort_order__fail",
  count_if(NULLIF(NULLIF(trim(replace("par_bucket_order", chr(13), '')), ''), 'NULL') IS NOT NULL AND try_cast(NULLIF(NULLIF(trim(replace("par_bucket_order", chr(13), '')), ''), 'NULL') AS integer) IS NULL) AS "par_bucket_order__fail"
FROM analytics_poc.raw_dim_par_bucket;
-- check: dim_par_bucket.typed_profile
SELECT
  count(*) AS row_count,
  approx_distinct("od_days") AS "od_days__distinct",
  count_if("od_days" IS NULL) AS "od_days__nulls",
  approx_distinct("par_bucket") AS "par_bucket__distinct",
  count_if("par_bucket" IS NULL) AS "par_bucket__nulls",
  approx_distinct("interval_split_yearly") AS "interval_split_yearly__distinct",
  count_if("interval_split_yearly" IS NULL) AS "interval_split_yearly__nulls",
  approx_distinct("interval_split_yearly_sort_order") AS "interval_split_yearly_sort_order__distinct",
  count_if("interval_split_yearly_sort_order" IS NULL) AS "interval_split_yearly_sort_order__nulls",
  approx_distinct("par_bucket_order") AS "par_bucket_order__distinct",
  count_if("par_bucket_order" IS NULL) AS "par_bucket_order__nulls"
FROM analytics_poc.v_dim_par_bucket;
-- check: dim_par_bucket.grain_uniqueness (od_days)
SELECT count(*) AS duplicate_groups, COALESCE(sum(n), 0) AS rows_in_duplicate_groups
FROM (SELECT "od_days", count(*) AS n FROM analytics_poc.v_dim_par_bucket GROUP BY "od_days" HAVING count(*) > 1);
